COLUMNS = {
    "user_id": 800,
    "event_type": 400,
    "payload": 6000,
    "ts": 400,
}

def scan_mb(columns, table):
    if columns == ["*"]:
        return sum(table.values())
    return sum(table[c] for c in columns)

q1 = ["user_id", "event_type"]
q2 = ["*"]
q3 = ["ts"]

m1 = scan_mb(q1, COLUMNS)
m2 = scan_mb(q2, COLUMNS)
m3 = scan_mb(q3, COLUMNS)

print(f"q1 scans {m1} MB")
print(f"q2 scans {m2} MB")
print(f"q3 scans {m3} MB")
print(f"SELECT * costs {m2 / m1:.1f}x more than q1")
